entries[81293] = { ["name"] = "Gestohlene Glücksbringer", ["text"] = "Questgegenstand\n\"Dieser Beutel ist mit Glücksbringern der Grummel gefüllt und riecht nach Räucherwerk und Duftölen.\"" }
entries[81319] = { ["name"] = "Ein Stapel Fackeln", ["text"] = "Questgegenstand\nEinzigartig\n\"Offensichtlich mehr als eine einfache Fackel. Die Yaungol benutzen so etwas als Totem oder Zauberfokus.\"" }
entries[81320] = { ["name"] = "Right-Handed Invis Knuckles", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Faustwaffe\n4 - 8 Schaden Tempo 2.60\n(2.31 Schaden pro Sekunde)\nHaltbarkeit 16 / 16\nVerkaufspreis:" }
entries[81321] = { ["name"] = "Left-Handed Invis Knuckles", ["text"] = "Wird beim Aufheben gebunden\nSchildhand Faustwaffe\n4 - 8 Schaden Tempo 2.60\n(2.31 Schaden pro Sekunde)\nHaltbarkeit 16 / 16\nVerkaufspreis:" }
entries[81324] = { ["name"] = "No Belt", ["text"] = "Questgegenstand\nEinzigartig\nTaille" }
entries[81325] = { ["name"] = "No Boots", ["text"] = "Questgegenstand\nEinzigartig\nFüße" }
entries[81326] = { ["name"] = "No Pants (No Legs)", ["text"] = "Questgegenstand\nEinzigartig\nBeine" }
entries[81354] = { ["name"] = "Zügel des azurblauen Wasserschreiters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenötigt Stufe 90\nBenötigt Geübtes Reiten\nBenötigt Die Angler\n- Ehrfürchtig\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier kann außerhalb von Schlachtfeldern auf dem Wasser wandeln.\nBeschwört einen reitbaren azurblauen Wasserschreiter oder gibt ihn wieder frei. Dieses Reittier kann außerhalb von Schlachtfeldern auf dem Wasser wandeln, bis es Schaden erleidet.\nVerkaufspreis:" }
entries[81355] = { ["name"] = "Bleichwindtotem", ["text"] = "Questgegenstand\n\"Dieses uralte Totem ist handgeschnitzt. Es ist mit Symbolen und Zeichnungen bedeckt, die Ihr nicht entziffern könnt.\"" }
entries[81356] = { ["name"] = "Shado-Pan-Fackel", ["text"] = "Questgegenstand\nBenutzen: Verbrennt die Leichen aller Dorfbewohner in einem Bereich. Verursacht 5 Sek. lang alle 9250 bis 10750 Feuerschaden. (2 Sek. Abklingzeit)\n\"Das Feuer verströmt den berauschenden Duft von Räucherwerk und Kräutern.\"" }
entries[81384] = { ["name"] = "Verderbte Perle der Tintenkiemen", ["text"] = "Questgegenstand\nEinzigartig (20)\n\"Eine tintenartige Trübung wirbelt unter der Oberfläche dieser Perle.\"" }
entries[81385] = { ["name"] = "Gestohlener Ritualstab der Tintenkiemen", ["text"] = "Questgegenstand\n\"Ein uralter Stab, mit dem die Seelen der Tintenkiemen an ihre Perlen und damit auch an den Weiher gebunden werden.\"" }
entries[81388] = { ["name"] = "Leuchtende Perlen der Tintenkiemen", ["text"] = "Questgegenstand\nEinzigartig\n\"So schwarz die Perlen im verderbten Zustand auch waren, so hell glänzen sie jetzt. Sie fühlen sich warm an.\"" }
entries[81393] = { ["name"] = "Chens volles Fass", ["text"] = "Questgegenstand\n\"Komplett mit Chens Kaiserbier gefüllt.\"" }
entries[81394] = { ["name"] = "Fass voll Grandy", ["text"] = "Questgegenstand\nBenutzen: Wärmt die Knochen. Belebt den Geist.\n\"(HAFTUNGSAUSSCHLUSS: Der wärmende Effekt stellt keine tatsächliche Erhöhung der Körpertemperatur dar. Nicht als medizinisches Behandlungsmittel gegen Unterkühlung geeignet.)\"" }
